    17→
    18→interface BridgeStoreState {
    19→  // WebSocket connection state
    20→  wsConnected: boolean;
    21→
    22→  // Bridge state (from WebSocket bridge_status messages)
    23→  status: BridgeStatus;
    24→  port: number;
    25→  networkInterface: string | null;
    26→  jarExists: boolean;
