     6→
     7→export interface TrackListParams {
     8→  limit?: number;
     9→  offset?: number;
    10→  sort_by?: string;
    11→  sort_desc?: boolean;
    12→}
    13→
    14→function buildTrackListUrl(params: TrackListParams): string {
    15→  const search = new URLSearchParams();
    16→  if (params.limit != null) search.set("limit", String(params.limit));
    17→  if (params.offset != null) search.set("offset", String(params.offset));
    18→  if (params.sort_by != null) search.set("sort_by", params.sort_by);
    19→  if (params.sort_desc != null) search.set("sort_desc", String(params.sort_desc));
    20→  const qs = search.toString();
    21→  return `/tracks${qs ? `?${qs}` : ""}`;
    22→}
    23→
    24→export function useTracks(params: TrackListParams = {}) {
    25→  return useQuery<TrackListResponse>({
    26→    queryKey: ["tracks", params],
    27→    queryFn: () => apiFetch<TrackListResponse>(buildTrackListUrl(params)),
    28→  });
    29→}
    30→
    31→export function useTrackAnalysis(fingerprint: string | null) {
    32→  return useQuery<TrackAnalysis>({
    33→    queryKey: ["track-analysis", fingerprint],
    34→    queryFn: () => apiFetch<TrackAnalysis>(`/tracks/${fingerprint}`),
    35→    enabled: fingerprint !== null,
    36→  });
    37→}
    38→
    39→export interface ResolveResult {
    40→  fingerprint: string;
    41→  title: string;
    42→  artist: string;
