    49→) {
    50→  return useQuery<ResolveResult>({
    51→    queryKey: ["resolve-track", sourcePlayer, sourceSlot, rekordboxId],
    52→    queryFn: () =>
    53→      apiFetch<ResolveResult>(
    54→        `/tracks/resolve/${sourcePlayer}/${sourceSlot}/${rekordboxId}`,
    55→      ),
    56→    enabled: rekordboxId !== null && rekordboxId > 0,
    57→  });
    58→}
