{'role': 'user', 'content': [{'tool_use_id': 'toolu_01SxmUoThwYYSJjdMHp6qW15', 'type': 'tool_result', 'content': '     1→import { useCallback } from "react";
     2→import { useQueryClient } from "@tanstack/react-query";
