    11→
    12→export interface DeckPanelProps {
    13→  deckNumber: 1 | 2;
    14→  player: PlayerInfo | undefined;
    15→  bridgeOverride: EmptyStateKind | null;
    16→}
    17→
    18→export function DeckPanel({ deckNumber, player, bridgeOverride }: DeckPanelProps) {
    19→  const queryClient = useQueryClient();
    20→  const rbId = player?.rekordbox_id ?? null;
    21→  const srcPlayer = player?.track_source_player ?? 0;
    22→  const srcSlot = player?.track_source_slot ?? "";
    23→
    24→  const handleRetryResolve = useCallback(() => {
    25→    queryClient.invalidateQueries({
    26→      queryKey: ["resolve-track", srcPlayer, srcSlot, rbId],
    27→    });
    28→  }, [queryClient, srcPlayer, srcSlot, rbId]);
    29→
    30→  const resolve = useResolveTrack(srcPlayer, srcSlot, rbId && rbId > 0 ? rbId : null);
    31→  const fingerprint = resolve.data?.fingerprint ?? null;
    32→  const analysis = useTrackAnalysis(fingerprint);
    33→
    34→  // Header
    35→  const stateLabel = player?.playback_state ?? "";
    36→  const stateBadge =
    37→    stateLabel === "playing"
    38→      ? "bg-green-900/50 text-green-300"
    39→      : stateLabel === "paused" || stateLabel === "cued"
    40→        ? "bg-amber-900/50 text-amber-300"
    41→        : "bg-gray-800 text-gray-400";
    42→
    43→  return (
    44→    <div className="rounded border border-gray-800 bg-gray-950 p-3 flex flex-col flex-1 min-h-0">
    45→      {/* Header bar */}
    46→      <div className="flex items-center justify-between mb-2">
    47→        <span className="text-xs font-semibold uppercase tracking-wider text-gray-500">
    48→          Deck {deckNumber}
    49→        </span>
    50→        <div className="flex items-center gap-2">
    51→          {player && (
    52→            <>
    53→              <span className={`px-2 py-0.5 rounded text-xs ${stateBadge}`}>
    54→                {stateLabel}
    55→              </span>
    56→              <span
    57→                className={`inline-block w-2 h-2 rounded-full ${player.is_on_air ? "bg-green-500" : "bg-gray-600"}`}
    58→              />
    59→            </>
    60→          )}
    61→        </div>
    62→      </div>
    63→
    64→      {/* Content */}
    65→      {renderContent()}
    66→    </div>
    67→  );
    68→
    69→  function renderContent() {
    70→    // Bridge-level overrides
    71→    if (bridgeOverride) {
    72→      return <DeckEmptyState kind={bridgeOverride} deckNumber={deckNumber} />;
    73→    }
    74→
    75→    // D1: No player data
    76→    if (!player) {
    77→      return <DeckEmptyState kind="no-player" deckNumber={deckNumber} />;
    78→    }
    79→
    80→    // D2: No track loaded
    81→    if (!rbId || rbId === 0) {
    82→      return <DeckEmptyState kind="no-track" deckNumber={deckNumber} />;
    83→    }
    84→
    85→    // D3: Resolution pending
    86→    if (resolve.isLoading) {
    87→      return <DeckEmptyState kind="resolving" deckNumber={deckNumber} />;
    88→    }
    89→
    90→    // D4: Not found
    91→    if (resolve.isError || (!resolve.isLoading && !fingerprint)) {
    92→      return (
    93→        <>
    94→          <DeckEmptyState
    95→            kind="not-found"
    96→            deckNumber={deckNumber}
    97→            rekordboxId={rbId}
    98→            sourcePlayer={srcPlayer}
    99→            sourceSlot={srcSlot}
   100→            player={player}
   101→            onRetry={handleRetryResolve}
   102→          />
   103→          <DeckMetadata player={player} analysis={null} />
   104→        </>
   105→      );
