    30→  if (idx < 0) return null;
    31→  const s = sections[idx];
    32→  const pct = (sec - s.start) / (s.end - s.start);
    33→  const bar = Math.min(s.bar_count, Math.floor(pct * s.bar_count) + 1);
    34→  return { section: s, index: idx, barInSection: bar, totalBars: s.bar_count, pct: pct * 100 };
    35→}
