    23→function findCurrentSectionIndex(sections: Section[], positionSec: number): number {
    24→  return sections.findIndex((s) => positionSec >= s.start && positionSec < s.end);
    25→}
    26→
    27→function findNextSection(sections: Section[], positionSec: number, currentIdx: number): Section | null {
    28→  if (currentIdx >= 0 && currentIdx < sections.length - 1) {
    29→    return sections[currentIdx + 1];
    30→  }
    31→  if (currentIdx < 0) {
    32→    const next = sections.find((s) => s.start > positionSec);
    33→    return next ?? null;
    34→  }
    35→  return null;
    36→}
    37→
    38→export interface SectionIndicatorProps {
    39→  sections: Section[];
    40→  positionMs: number | null;
    41→}
    42→
    43→export function SectionIndicator({ sections, positionMs }: SectionIndicatorProps) {
    44→  if (!sections.length) {
    45→    return <div className="text-gray-500 text-xs px-2 h-6 flex items-center">No sections</div>;
    46→  }
    47→
    48→  if (positionMs === null) {
    49→    return <div className="text-gray-500 text-xs px-2 h-6 flex items-center">—</div>;
    50→  }
    51→
    52→  const positionSec = positionMs / 1000;
    53→  const currentIdx = findCurrentSectionIndex(sections, positionSec);
    54→  const current = currentIdx >= 0 ? sections[currentIdx] : null;
    55→  const next = findNextSection(sections, positionSec, currentIdx);
    56→
    57→  if (!current) {
    58→    return (
