    65→        )}
    66→      </div>
    67→    );
    68→  }
    69→
    70→  const progress = Math.min(1, Math.max(0, (positionSec - current.start) / (current.end - current.start)));
    71→  const barColor = SECTION_BAR_COLORS[current.label] ?? "bg-gray-500";
    72→  const textColor = SECTION_TEXT_COLORS[current.label] ?? "text-gray-400";
    73→
    74→  return (
    75→    <div className="flex items-center gap-2 h-6 px-2">
    76→      <span className={`text-xs font-medium ${textColor}`}>{current.label}</span>
    77→      <div className="h-1 rounded-full bg-gray-800 flex-1">
